"""Fibonacci anyon gate set: structural identities (standalone)."""
from __future__ import annotations
import cmath
import math
from typing import Tuple

Mat = Tuple[Tuple[complex, complex], Tuple[complex, complex]]
I2: Mat = ((1 + 0j, 0j), (0j, 1 + 0j))
GOLD: float = (1 + math.sqrt(5)) / 2
TAU: float = 1 / GOLD


def mul(X: Mat, Y: Mat) -> Mat:
    return (
        (X[0][0]*Y[0][0] + X[0][1]*Y[1][0], X[0][0]*Y[0][1] + X[0][1]*Y[1][1]),
        (X[1][0]*Y[0][0] + X[1][1]*Y[1][0], X[1][0]*Y[0][1] + X[1][1]*Y[1][1]),
    )


def conj_T(X: Mat) -> Mat:
    return ((X[0][0].conjugate(), X[1][0].conjugate()),
            (X[0][1].conjugate(), X[1][1].conjugate()))


def approx_eq(X: Mat, Y: Mat, tol: float = 1e-8) -> bool:
    return all(abs(X[i][j] - Y[i][j]) < tol for i in range(2) for j in range(2))


def fib_F() -> Mat:
    s = math.sqrt(TAU)
    return ((TAU + 0j, s + 0j), (s + 0j, -TAU + 0j))


def fib_R() -> Mat:
    return ((cmath.exp(1j * (-4 * math.pi / 5)), 0j),
            (0j, cmath.exp(1j * (3 * math.pi / 5))))


if __name__ == "__main__":
    F, R = fib_F(), fib_R()
    print("phi^2 = phi + 1 :", abs(GOLD**2 - (GOLD + 1)) < 1e-12)
    print("F*F == I        :", approx_eq(mul(F, F), I2))
    print("R^dag R == I    :", approx_eq(mul(conj_T(R), R), I2))
    B1, B2 = R, mul(mul(F, R), F)
    print("B1 B2 B1 == B2 B1 B2 :",
          approx_eq(mul(mul(B1, B2), B1), mul(mul(B2, B1), B2)))

